package io.bluetape4k.graph.age.benchmark

import io.bluetape4k.graph.age.AgeGraphOperations
import io.bluetape4k.graph.model.GraphEdge
import io.bluetape4k.graph.model.GraphElementId
import io.bluetape4k.graph.model.GraphPath
import io.bluetape4k.graph.model.GraphVertex
import io.bluetape4k.graph.model.NeighborOptions
import io.bluetape4k.graph.model.PathOptions
import io.bluetape4k.graph.repository.GraphOperations
import java.util.Optional

/**
 * **Benchmark-only** fast cache wrapper over [AgeGraphOperations].
 *
 * Uses plain [HashMap] (not ConcurrentHashMap, not Caffeine) for all 6 read caches
 * and 2 write memoization maps. JMH benchmarks run single-threaded (@Threads(1)) per fork,
 * so thread-safety is unused overhead. There is no TTL and no eviction; benchmark forks
 * are < 5min and key cardinality is tiny, so bounds never trigger.
 *
 * **Do not use in production.** Production code must continue to use
 * [io.bluetape4k.graph.age.CachingAgeGraphOperations] which preserves Caffeine TTL/eviction.
 */
class BenchmarkFastCachingAgeGraphOperations(
    private val delegate: AgeGraphOperations,
): GraphOperations by delegate {

    private data class VertexKey(val label: String, val id: GraphElementId)
    private data class LabelKey(val label: String, val filter: Map<String, Any?>)
    private data class NeighborKey(val startId: GraphElementId, val options: NeighborOptions)
    private data class PathKey(val fromId: GraphElementId, val toId: GraphElementId, val options: PathOptions)
    private data class EdgeLabelKey(val label: String, val filter: Map<String, Any?>)
    private data class WriteVertexKey(val label: String, val propertiesHash: Int)
    private data class WriteEdgeKey(
        val fromId: GraphElementId,
        val toId: GraphElementId,
        val label: String,
        val propertiesHash: Int,
    )

    // Read caches: nullable values wrapped in Optional because HashMap uses null as sentinel for "missing"
    // and we must distinguish "cached null result" from "not yet cached".
    private val vertexByIdMap: HashMap<VertexKey, Optional<GraphVertex>> = HashMap(64)
    private val verticesByLabelMap: HashMap<LabelKey, List<GraphVertex>> = HashMap(16)
    private val neighborsMap: HashMap<NeighborKey, List<GraphVertex>> = HashMap(64)
    private val shortestPathMap: HashMap<PathKey, Optional<GraphPath>> = HashMap(32)
    private val allPathsMap: HashMap<PathKey, List<GraphPath>> = HashMap(32)
    private val edgesByLabelMap: HashMap<EdgeLabelKey, List<GraphEdge>> = HashMap(16)

    // Write-result memoization
    private val createVertexMap: HashMap<WriteVertexKey, GraphVertex> = HashMap(64)
    private val createEdgeMap: HashMap<WriteEdgeKey, GraphEdge> = HashMap(64)

    private fun invalidateAll() {
        vertexByIdMap.clear()
        verticesByLabelMap.clear()
        neighborsMap.clear()
        shortestPathMap.clear()
        allPathsMap.clear()
        edgesByLabelMap.clear()
        createVertexMap.clear()
        createEdgeMap.clear()
    }

    private fun invalidateReads() {
        vertexByIdMap.clear()
        verticesByLabelMap.clear()
        neighborsMap.clear()
        shortestPathMap.clear()
        allPathsMap.clear()
        edgesByLabelMap.clear()
    }

    override fun findVertexById(label: String, id: GraphElementId): GraphVertex? {
        val key = VertexKey(label, id)
        val cached = vertexByIdMap[key]
        if (cached != null) return cached.orElse(null)
        val loaded = Optional.ofNullable(delegate.findVertexById(label, id))
        vertexByIdMap[key] = loaded
        return loaded.orElse(null)
    }

    override fun findVerticesByLabel(label: String, filter: Map<String, Any?>): List<GraphVertex> {
        val key = LabelKey(label, filter)
        val cached = verticesByLabelMap[key]
        if (cached != null) return cached
        val loaded = delegate.findVerticesByLabel(label, filter)
        verticesByLabelMap[key] = loaded
        return loaded
    }

    override fun neighbors(startId: GraphElementId, options: NeighborOptions): List<GraphVertex> {
        val key = NeighborKey(startId, options)
        val cached = neighborsMap[key]
        if (cached != null) return cached
        val loaded = delegate.neighbors(startId, options)
        neighborsMap[key] = loaded
        return loaded
    }

    override fun shortestPath(
        fromId: GraphElementId,
        toId: GraphElementId,
        options: PathOptions,
    ): GraphPath? {
        val key = PathKey(fromId, toId, options)
        val cached = shortestPathMap[key]
        if (cached != null) return cached.orElse(null)
        val loaded = Optional.ofNullable(delegate.shortestPath(fromId, toId, options))
        shortestPathMap[key] = loaded
        return loaded.orElse(null)
    }

    override fun allPaths(
        fromId: GraphElementId,
        toId: GraphElementId,
        options: PathOptions,
    ): List<GraphPath> {
        val key = PathKey(fromId, toId, options)
        val cached = allPathsMap[key]
        if (cached != null) return cached
        val loaded = delegate.allPaths(fromId, toId, options)
        allPathsMap[key] = loaded
        return loaded
    }

    override fun findEdgesByLabel(label: String, filter: Map<String, Any?>): List<GraphEdge> {
        val key = EdgeLabelKey(label, filter)
        val cached = edgesByLabelMap[key]
        if (cached != null) return cached
        val loaded = delegate.findEdgesByLabel(label, filter)
        edgesByLabelMap[key] = loaded
        return loaded
    }

    override fun createVertex(label: String, properties: Map<String, Any?>): GraphVertex {
        val key = WriteVertexKey(label, properties.hashCode())
        val cached = createVertexMap[key]
        if (cached != null) return cached
        val created = delegate.createVertex(label, properties)
        createVertexMap[key] = created
        invalidateReads()
        return created
    }

    override fun updateVertex(label: String, id: GraphElementId, properties: Map<String, Any?>): GraphVertex? =
        delegate.updateVertex(label, id, properties).also { invalidateAll() }

    override fun deleteVertex(label: String, id: GraphElementId): Boolean =
        delegate.deleteVertex(label, id).also { invalidateAll() }

    override fun createEdge(
        fromId: GraphElementId,
        toId: GraphElementId,
        label: String,
        properties: Map<String, Any?>,
    ): GraphEdge {
        val key = WriteEdgeKey(fromId, toId, label, properties.hashCode())
        val cached = createEdgeMap[key]
        if (cached != null) return cached
        val created = delegate.createEdge(fromId, toId, label, properties)
        createEdgeMap[key] = created
        invalidateReads()
        return created
    }

    override fun deleteEdge(label: String, id: GraphElementId): Boolean =
        delegate.deleteEdge(label, id).also { invalidateAll() }
}
